import "./Footer.css";
import logo from "../../img/logoOne.png";

function Footer() {
  return (
    <footer className="footer">
      <a className="footer-logo" href="#top">
        <img src={logo} alt="24/7 Forecast" />
      </a>

      <div className="footer-address">
        <p>Address</p>
        <span>Svobody str. 35</span>
        <span>Kyiv</span>
        <span>Ukraine</span>
      </div>

      <div className="footer-social">
        <p>Contact us</p>

        <div className="footer-icons">
          {/* ЗАМЕНИ # НА ССЫЛКУ СВОЕГО INSTAGRAM */}
          <a href="https://www.instagram.com/" target="_blank" rel="noreferrer" aria-label="Instagram">
            {/* ВСТАВЬ СЮДА СВОЮ ИКОНКУ INSTAGRAM */}
            Instagram
          </a>

          {/* ЗАМЕНИ # НА ССЫЛКУ СВОЕГО FACEBOOK */}
          <a href="https://www.facebook.com/" target="_blank" rel="noreferrer" aria-label="Facebook">
            {/* ВСТАВЬ СЮДА СВОЮ ИКОНКУ FACEBOOK */}
            Facebook
          </a>

          {/* ЗАМЕНИ # НА ССЫЛКУ СВОЕГО WHATSAPP */}
          <a href="https://www.whatsapp.com/" target="_blank" rel="noreferrer" aria-label="WhatsApp">
            {/* ВСТАВЬ СЮДА СВОЮ ИКОНКУ WHATSAPP */}
            WhatsApp
          </a>
        </div>
      </div>
    </footer>
  );
}

export default Footer;
